R["hsga-p3-inversions"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    vector<int> vals(a);\n    sort(vals.begin(), vals.end());\n    vals.erase(unique(vals.begin(), vals.end()), vals.end());\n    auto rk = [&](int x) { return int(lower_bound(vals.begin(), vals.end(), x) - vals.begin()) + 1; };\n    int m = (int)vals.size();\n    vector<int> fen(m + 1, 0);\n    auto upd = [&](int i, int d) { for (; i <= m; i += i & (-i)) fen[i] += d; };\n    auto pref = [&](int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };\n    long long inv = 0;\n    for (int i = 0; i < n; ++i) {\n        int r = rk(a[i]);\n        inv += (long long)i - pref(r);   // seen strictly greater than a[i]\n        upd(r, 1);\n    }\n    out << inv << \"\\n\";\n}\n";
W["hsga-p3-inversions"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: counts pairs with a[i] >= a[j] \u2014 equal elements are treated\n    // as inversions (double-counted), and O(n^2) blows the limit anyway.\n    long long inv = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = i + 1; j < n; ++j)\n            if (a[i] >= a[j]) ++inv;\n    out << inv << \"\\n\";\n}\n";
R["hsga-cp-m4-lca"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> up(18, vector<int>(n + 1, 0));\n    vector<int> dep(n + 1, 0);\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    // iterative depth\n    vector<int> st; st.push_back(1);\n    while (!st.empty()) {\n        int u = st.back(); st.pop_back();\n        for (int c : ch[u]) { dep[c] = dep[u] + 1; st.push_back(c); }\n    }\n    for (int v = 1; v <= n; ++v) up[0][v] = par[v];\n    for (int k = 1; k < 18; ++k)\n        for (int v = 1; v <= n; ++v) up[k][v] = up[k-1][up[k-1][v]];\n    auto lift = [&](int v, long long k) {\n        for (int b = 0; b < 18 && v; ++b)\n            if (k >> b & 1) v = up[b][v];\n        return v;\n    };\n    auto lca = [&](int u, int v) {\n        if (dep[u] < dep[v]) swap(u, v);\n        u = lift(u, dep[u] - dep[v]);\n        if (u == v) return u;\n        for (int k = 17; k >= 0; --k)\n            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n        return par[u];\n    };\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"ANC\") { int v; long long k; in >> v >> k; out << lift(v, k) << \"\\n\"; }\n        else { int u, v; in >> u >> v; out << lca(u, v) << \"\\n\"; }\n    }\n}\n";
W["hsga-cp-m4-lca"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> up(18, vector<int>(n + 1, 0));\n    vector<int> dep(n + 1, 0);\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> st; st.push_back(1);\n    while (!st.empty()) {\n        int u = st.back(); st.pop_back();\n        for (int c : ch[u]) { dep[c] = dep[u] + 1; st.push_back(c); }\n    }\n    for (int v = 1; v <= n; ++v) up[0][v] = par[v];\n    for (int k = 1; k < 18; ++k)\n        for (int v = 1; v <= n; ++v) up[k][v] = up[k-1][up[k-1][v]];\n    auto lift = [&](int v, long long k) {\n        for (int b = 0; b < 18 && v; ++b)\n            if (k >> b & 1) v = up[b][v];\n        return v;\n    };\n    auto lca = [&](int u, int v) {\n        if (dep[u] < dep[v]) swap(u, v);\n        u = lift(u, dep[u] - dep[v]);\n        // WRONG: missing the early exit when u == v after equalization \u2014\n        // when one node is an ancestor of the other, the descent phase\n        // then walks both nodes PAST the true LCA.\n        for (int k = 17; k >= 0; --k)\n            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n        return par[u];\n    };\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"ANC\") { int v; long long k; in >> v >> k; out << lift(v, k) << \"\\n\"; }\n        else { int u, v; in >> u >> v; out << lca(u, v) << \"\\n\"; }\n    }\n}\n";
