R["hsga-p4-lca"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> up(18, vector<int>(n + 1, 0));\n    vector<int> dep(n + 1, 0);\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    // iterative depth\n    vector<int> st; st.push_back(1);\n    while (!st.empty()) {\n        int u = st.back(); st.pop_back();\n        for (int c : ch[u]) { dep[c] = dep[u] + 1; st.push_back(c); }\n    }\n    for (int v = 1; v <= n; ++v) up[0][v] = par[v];\n    for (int k = 1; k < 18; ++k)\n        for (int v = 1; v <= n; ++v) up[k][v] = up[k-1][up[k-1][v]];\n    auto lift = [&](int v, long long k) {\n        for (int b = 0; b < 18 && v; ++b)\n            if (k >> b & 1) v = up[b][v];\n        return v;\n    };\n    auto lca = [&](int u, int v) {\n        if (dep[u] < dep[v]) swap(u, v);\n        u = lift(u, dep[u] - dep[v]);\n        if (u == v) return u;\n        for (int k = 17; k >= 0; --k)\n            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n        return par[u];\n    };\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"ANC\") { int v; long long k; in >> v >> k; out << lift(v, k) << \"\\n\"; }\n        else { int u, v; in >> u >> v; out << lca(u, v) << \"\\n\"; }\n    }\n}\n";
W["hsga-p4-lca"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    // WRONG: climbs both nodes one parent step at a time until they meet \u2014\n    // O(depth) per query; on a 200000-node path with far-apart queries\n    // that is O(n) per query and times out.\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"ANC\") { int v; long long k; in >> v >> k; while (k-- && v) v = par[v]; out << v << \"\\n\"; }\n        else {\n            int u, v; in >> u >> v;\n            vector<int> dep(n + 1, 0);\n            // recompute depth by walking (already O(depth)) then climb\n            vector<int> a; int x = u;\n            while (x) { a.push_back(x); x = par[x]; }\n            vector<int> b; x = v;\n            while (x) { b.push_back(x); x = par[x]; }\n            int iu = (int)a.size() - 1, iv = (int)b.size() - 1;\n            while (iu > 0 && iv > 0 && a[iu-1] == b[iv-1]) { --iu; --iv; }\n            out << a[iu] << \"\\n\";\n        }\n    }\n}\n";
R["hsga-cp-m5-euler"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> tin(n + 1), tout(n + 1);\n    // iterative euler tour\n    vector<pair<int, bool>> st; st.push_back({1, false});\n    int timer = 1;\n    while (!st.empty()) {\n        auto [u, done] = st.back(); st.pop_back();\n        if (done) { tout[u] = timer - 1; continue; }\n        tin[u] = timer++;\n        st.push_back({u, true});\n        for (int i = (int)ch[u].size() - 1; i >= 0; --i) st.push_back({ch[u][i], false});\n    }\n    vector<long long> fen(n + 1, 0);\n    auto upd = [&](int i, long long d) { for (; i <= n; i += i & (-i)) fen[i] += d; };\n    auto pref = [&](int i) { long long s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"SA\") { int v; long long x; in >> v >> x; upd(tin[v], x); if (tout[v] + 1 <= n) upd(tout[v] + 1, -x); }\n        else { int v; in >> v; out << pref(tin[v]) << \"\\n\"; }\n    }\n}\n";
W["hsga-cp-m5-euler"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> tin(n + 1), tout(n + 1);\n    vector<pair<int, bool>> st; st.push_back({1, false});\n    int timer = 1;\n    while (!st.empty()) {\n        auto [u, done] = st.back(); st.pop_back();\n        if (done) { tout[u] = timer - 1; continue; }\n        tin[u] = timer++;\n        st.push_back({u, true});\n        for (int i = (int)ch[u].size() - 1; i >= 0; --i) st.push_back({ch[u][i], false});\n    }\n    vector<long long> add(n + 1, 0);\n    // WRONG: applies each subtree add by walking the subtree's node list \u2014\n    // O(subtree size) per op; 10^5 root adds on n = 2\u00b710^5 is 2\u00b710^10 steps.\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"SA\") {\n            int v; long long x; in >> v >> x;\n            vector<pair<int, bool>> s2; s2.push_back({v, false});\n            while (!s2.empty()) {\n                auto [u, d] = s2.back(); s2.pop_back();\n                add[u] += x;\n                if (!d) { s2.push_back({u, true}); for (int c : ch[u]) s2.push_back({c, false}); }\n            }\n        } else { int v; in >> v; out << add[v] << \"\\n\"; }\n    }\n}\n";
R["hsga-p5-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> tin(n + 1), tout(n + 1);\n    // iterative euler tour\n    vector<pair<int, bool>> st; st.push_back({1, false});\n    int timer = 1;\n    while (!st.empty()) {\n        auto [u, done] = st.back(); st.pop_back();\n        if (done) { tout[u] = timer - 1; continue; }\n        tin[u] = timer++;\n        st.push_back({u, true});\n        for (int i = (int)ch[u].size() - 1; i >= 0; --i) st.push_back({ch[u][i], false});\n    }\n    vector<long long> fen(n + 1, 0);\n    auto upd = [&](int i, long long d) { for (; i <= n; i += i & (-i)) fen[i] += d; };\n    auto pref = [&](int i) { long long s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"SA\") { int v; long long x; in >> v >> x; upd(tin[v], x); if (tout[v] + 1 <= n) upd(tout[v] + 1, -x); }\n        else { int v; in >> v; out << pref(tin[v]) << \"\\n\"; }\n    }\n}\n";
W["hsga-p5-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<long long> add(n + 1, 0);\n    // WRONG: walks the whole subtree per add \u2014 O(size) per op.\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"SA\") {\n            int v; long long x; in >> v >> x;\n            vector<pair<int, bool>> s2; s2.push_back({v, false});\n            while (!s2.empty()) {\n                auto [u, d] = s2.back(); s2.pop_back();\n                if (!d) { add[u] += x; s2.push_back({u, true}); for (int c : ch[u]) s2.push_back({c, false}); }\n            }\n        } else { int v; in >> v; out << add[v] << \"\\n\"; }\n    }\n}\n";
R["hsga-p5-pathadd"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> tin(n + 1), tout(n + 1), dep(n + 1, 0);\n    vector<pair<int, bool>> st; st.push_back({1, false});\n    int timer = 1;\n    while (!st.empty()) {\n        auto [u, done] = st.back(); st.pop_back();\n        if (done) { tout[u] = timer - 1; continue; }\n        tin[u] = timer++;\n        st.push_back({u, true});\n        for (int i = (int)ch[u].size() - 1; i >= 0; --i) { dep[ch[u][i]] = dep[u] + 1; st.push_back({ch[u][i], false}); }\n    }\n    vector<vector<int>> up(18, vector<int>(n + 1, 0));\n    for (int v = 1; v <= n; ++v) up[0][v] = par[v];\n    for (int k = 1; k < 18; ++k)\n        for (int v = 1; v <= n; ++v) up[k][v] = up[k-1][up[k-1][v]];\n    auto lca = [&](int u, int v) {\n        if (dep[u] < dep[v]) swap(u, v);\n        int d = dep[u] - dep[v];\n        for (int k = 0; k < 18; ++k) if (d >> k & 1) u = up[k][u];\n        if (u == v) return u;\n        for (int k = 17; k >= 0; --k)\n            if (up[k][u] != up[k][v]) { u = up[k][u]; v = up[k][v]; }\n        return par[u];\n    };\n    vector<long long> fen(n + 1, 0);\n    auto upd = [&](int i, long long d) { for (; i <= n; i += i & (-i)) fen[i] += d; };\n    auto pref = [&](int i) { long long s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"PA\") {\n            int u, v; long long x; in >> u >> v >> x;\n            int l = lca(u, v);\n            upd(tin[u], x); upd(tin[v], x); upd(tin[l], -x);\n            if (par[l]) upd(tin[par[l]], -x);\n        } else {\n            int w; in >> w;\n            out << pref(tout[w]) - pref(tin[w] - 1) << \"\\n\";\n        }\n    }\n}\n";
W["hsga-p5-pathadd"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<long long> add(n + 1, 0);\n    // WRONG: adds x by walking u..v node-by-node (climb the deeper, then\n    // both) \u2014 O(depth) per op; on the path graph with far endpoints that is\n    // O(n) per op and 10^5 ops time out.\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"PA\") {\n            int u, v; long long x; in >> u >> v >> x;\n            // walk both up to root, marking by depth matching\n            vector<int> au, av;\n            for (int z = u; z; z = par[z]) au.push_back(z);\n            for (int z = v; z; z = par[z]) av.push_back(z);\n            if (au.size() < av.size()) swap(au, av), swap(u, v);\n            int du = (int)au.size() - (int)av.size();\n            while (du--) { add[u] += x; u = par[u]; }\n            int vv = v;\n            while (u != vv) { add[u] += x; add[vv] += x; u = par[u]; vv = par[vv]; }\n            add[u] += x;\n        } else { int w; in >> w; out << add[w] << \"\\n\"; }\n    }\n}\n";
R["hsga-p5-marks"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n, q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<vector<int>> ch(n + 1, vector<int>());\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> tin(n + 1), tout(n + 1);\n    vector<pair<int, bool>> st; st.push_back({1, false});\n    int timer = 1;\n    while (!st.empty()) {\n        auto [u, done] = st.back(); st.pop_back();\n        if (done) { tout[u] = timer - 1; continue; }\n        tin[u] = timer++;\n        st.push_back({u, true});\n        for (int i = (int)ch[u].size() - 1; i >= 0; --i) st.push_back({ch[u][i], false});\n    }\n    vector<long long> fen(n + 1, 0);\n    auto upd = [&](int i, long long d) { for (; i <= n; i += i & (-i)) fen[i] += d; };\n    auto pref = [&](int i) { long long s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };\n    vector<char> marked(n + 1, 0);\n    for (int i = 0; i < q; ++i) {\n        string tp; in >> tp;\n        if (tp == \"TOG\") { int v; in >> v; long long d = marked[v] ? -1 : 1; marked[v] ^= 1; upd(tin[v], d); }\n        else { int v; in >> v; out << pref(tout[v]) - pref(tin[v] - 1) << \"\\n\"; }\n    }\n}\n";
