R["hsga-p6-diameter"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<long long> w(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> w[v];\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> order; order.reserve(n);\n    vector<pair<int, bool>> st; st.push_back({1, false});\n    while (!st.empty()) {\n        auto [u, d] = st.back(); st.pop_back();\n        if (d) { order.push_back(u); continue; }\n        st.push_back({u, true});\n        for (int c : ch[u]) st.push_back({c, false});\n    }\n    vector<long long> h(n + 1, 0);\n    long long best = 0;\n    for (int u : order) {\n        long long h1 = 0, h2 = 0;\n        for (int c : ch[u]) {\n            long long hh = h[c] + w[c];\n            if (hh > h1) { h2 = h1; h1 = hh; } else if (hh > h2) h2 = hh;\n        }\n        best = max(best, h1 + h2);\n        h[u] = h1;\n    }\n    out << best << \"\\n\";\n}\n";
W["hsga-p6-diameter"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n    int n; in >> n;\n    vector<int> par(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    vector<long long> w(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> w[v];\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) ch[par[v]].push_back(v);\n    vector<int> order; order.reserve(n);\n    vector<pair<int, bool>> st; st.push_back({1, false});\n    while (!st.empty()) {\n        auto [u, d] = st.back(); st.pop_back();\n        if (d) { order.push_back(u); continue; }\n        st.push_back({u, true});\n        for (int c : ch[u]) st.push_back({c, false});\n    }\n    vector<long long> h(n + 1, 0);\n    // WRONG: cross term checked only at the root \u2014 misses diameters that\n    // bend deeper (overestimates them with the depth, or misses entirely).\n    long long h1 = 0, h2 = 0;\n    for (int u : order) {\n        long long a = 0, b = 0;\n        for (int c : ch[u]) {\n            long long hh = h[c] + w[c];\n            if (hh > a) { b = a; a = hh; } else if (hh > b) b = hh;\n        }\n        h[u] = a;\n    }\n    for (int c : ch[1]) {\n        long long hh = h[c] + w[c];\n        if (hh > h1) { h2 = h1; h1 = hh; } else if (hh > h2) h2 = hh;\n    }\n    out << h1 + h2 << \"\\n\";\n}\n";
