W["hsga-p8-complabel"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n, m; in >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; in >> u >> v;\n        adj[u].push_back(v);\n    }\n    // WRONG: for each node, BFS and assign same-group labels by mutual\n    // reachability discovered per node \u2014 O(n\u00b7(n+m)) total.\n    vector<int> lab(n + 1, 0);\n    int next = 0;\n    for (int s = 1; s <= n; ++s) {\n        if (lab[s]) continue;\n        ++next;\n        // forward from s\n        vector<char> fwd(n + 1, 0);\n        vector<int> st; st.push_back(s); fwd[s] = 1;\n        while (!st.empty()) {\n            int u = st.back(); st.pop_back();\n            for (int v : adj[u]) if (!fwd[v]) { fwd[v] = 1; st.push_back(v); }\n        }\n        for (int v = 1; v <= n; ++v) {\n            if (lab[v] || !fwd[v]) continue;\n            // check v reaches s?\n            vector<char> bk(n + 1, 0);\n            vector<int> st2; st2.push_back(v); bk[v] = 1;\n            while (!st2.empty()) {\n                int u = st2.back(); st2.pop_back();\n                for (int w : adj[u]) if (!bk[w]) { bk[w] = 1; st2.push_back(w); }\n            }\n            if (bk[s]) { lab[v] = next; }\n        }\n        if (!lab[s]) lab[s] = next;\n    }\n    for (int v = 1; v <= n; ++v) {\n        if (v > 1) out << ' ';\n        out << lab[v];\n    }\n    out << \"\\n\";\n}\n";
R["hsga-cp-m9-flowval"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n, m, s, t; in >> n >> m >> s >> t;\n    vector<long long> cap(2 * m, 0);\n    vector<vector<int>> g(n + 1);\n    vector<int> to(2 * m, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long c; in >> u >> v >> c;\n        to[2*i] = v; cap[2*i] = c; g[u].push_back(2*i);\n        to[2*i+1] = u; cap[2*i+1] = 0; g[v].push_back(2*i+1);\n    }\n    vector<int> level(n + 1, -1), it(n + 1, 0);\n    auto bfs = [&]() {\n        fill(level.begin(), level.end(), -1);\n        level[s] = 0;\n        queue<int> q; q.push(s);\n        while (!q.empty()) {\n            int u = q.front(); q.pop();\n            for (int e : g[u]) if (cap[e] > 0 && level[to[e]] == -1) {\n                level[to[e]] = level[u] + 1; q.push(to[e]);\n            }\n        }\n        return level[t] != -1;\n    };\n    auto dfs = [&](auto&& self, int u, long long f) -> long long {\n        if (u == t) return f;\n        for (int& i = it[u]; i < (int)g[u].size(); ++i) {\n            int e = g[u][i], v = to[e];\n            if (cap[e] > 0 && level[v] == level[u] + 1) {\n                long long d = self(self, v, min(f, cap[e]));\n                if (d > 0) { cap[e] -= d; cap[e^1] += d; return d; }\n            }\n        }\n        return 0;\n    };\n    long long flow = 0;\n    while (bfs()) {\n        fill(it.begin(), it.end(), 0);\n        while (long long d = dfs(dfs, s, LLONG_MAX)) flow += d;\n    }\n    out << flow << \"\\n\";\n}\n";
W["hsga-cp-m9-flowval"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: prints the capacity of the widest single s-t path (a variant of\n    // the widest-path greedy) \u2014 overestimates whenever the min cut < widest path.\n    int n, m, s, t; in >> n >> m >> s >> t;\n    vector<vector<pair<int, long long>>> g(n + 1);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long c; in >> u >> v >> c;\n        g[u].push_back({v, c});\n    }\n    // widest path: max over paths of min edge\n    vector<long long> best(n + 1, -1);\n    priority_queue<pair<long long, int>> pq;\n    best[s] = LLONG_MAX;\n    pq.push({LLONG_MAX, s});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d < best[u]) continue;\n        for (auto& [v, c] : g[u]) {\n            long long nd = min(d, c);\n            if (nd > best[v]) { best[v] = nd; pq.push({nd, v}); }\n        }\n    }\n    out << (best[t] == LLONG_MAX ? best[t] : best[t]) << \"\\n\";\n}\n";
R["hsga-p9-flowval"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n, m, s, t; in >> n >> m >> s >> t;\n    vector<long long> cap(2 * m, 0);\n    vector<vector<int>> g(n + 1);\n    vector<int> to(2 * m, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long c; in >> u >> v >> c;\n        to[2*i] = v; cap[2*i] = c; g[u].push_back(2*i);\n        to[2*i+1] = u; cap[2*i+1] = 0; g[v].push_back(2*i+1);\n    }\n    long long flow = 0;\n    while (true) {\n        // BFS\n        vector<int> par(n + 1, -1), pedge(n + 1, -1);\n        par[s] = s;\n        queue<int> q; q.push(s);\n        while (!q.empty() && par[t] == -1) {\n            int u = q.front(); q.pop();\n            for (int e : g[u]) {\n                if (cap[e] > 0 && par[to[e]] == -1) {\n                    par[to[e]] = u; pedge[to[e]] = e; q.push(to[e]);\n                }\n            }\n        }\n        if (par[t] == -1) break;\n        long long b = LLONG_MAX;\n        for (int v = t; v != s; v = par[v]) b = min(b, cap[pedge[v]]);\n        for (int v = t; v != s; v = par[v]) { cap[pedge[v]] -= b; cap[pedge[v]^1] += b; }\n        flow += b;\n    }\n    out << flow << \"\\n\";\n}\n";
W["hsga-p9-flowval"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n, m, s, t; in >> n >> m >> s >> t;\n    vector<long long> cap(2 * m, 0);\n    vector<vector<int>> g(n + 1);\n    vector<int> to(2 * m, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long c; in >> u >> v >> c;\n        to[2*i] = v; cap[2*i] = c; g[u].push_back(2*i);\n        to[2*i+1] = u; cap[2*i+1] = 0; g[v].push_back(2*i+1);\n    }\n    // WRONG: single DFS s->t each round, but the DFS commits to the FIRST\n    // path greedily and never revisits arcs through residual back-edges\n    // (skips any edge whose pair was already used).\n    long long flow = 0;\n    vector<char> arcUsed(2 * m, 0);\n    while (true) {\n        vector<int> par(n + 1, -1), pedge(n + 1, -1);\n        // DFS with residual-arc ban\n        vector<char> vis(n + 1, 0);\n        vector<int> st; st.push_back(s); vis[s] = 1;\n        while (!st.empty()) {\n            int u = st.back(); st.pop_back();\n            if (u == t) break;\n            for (int e : g[u]) {\n                int v = to[e];\n                if (cap[e] > 0 && !vis[v] && !(e % 2 == 1 && arcUsed[e])) {\n                    vis[v] = 1; par[v] = u; pedge[v] = e; st.push_back(v);\n                }\n            }\n        }\n        if (par[t] == -1) break;\n        long long b = LLONG_MAX;\n        for (int v = t; v != s; v = par[v]) b = min(b, cap[pedge[v]]);\n        for (int v = t; v != s; v = par[v]) {\n            cap[pedge[v]] -= b;\n            if (pedge[v] % 2 == 0) arcUsed[pedge[v]] = 1;  // wrong: once used, forward arc frozen\n        }\n        flow += b;\n    }\n    out << flow << \"\\n\";\n}\n";
R["hsga-p9-match"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int L, R, m; in >> L >> R >> m;\n    int s = L + R + 1, t = L + R + 2, N = L + R + 2;\n    vector<long long> cap(2 * (m + L + R), 0);\n    vector<vector<int>> g(N + 1);\n    vector<int> to(2 * (m + L + R), 0);\n    int e = 0;\n    auto add = [&](int u, int v, long long c) {\n        to[e] = v; cap[e] = c; g[u].push_back(e); ++e;\n        to[e] = u; cap[e] = 0; g[v].push_back(e); ++e;\n    };\n    for (int i = 0; i < m; ++i) { int u, v; in >> u >> v; add(u, L + v, 1); }\n    for (int u = 1; u <= L; ++u) add(s, u, 1);\n    for (int v = 1; v <= R; ++v) add(L + v, t, 1);\n    long long flow = 0;\n    while (true) {\n        vector<int> par(N + 1, -1), pedge(N + 1, -1);\n        par[s] = s;\n        queue<int> q; q.push(s);\n        while (!q.empty() && par[t] == -1) {\n            int u = q.front(); q.pop();\n            for (int ei : g[u]) {\n                if (cap[ei] > 0 && par[to[ei]] == -1) {\n                    par[to[ei]] = u; pedge[to[ei]] = ei; q.push(to[ei]);\n                }\n            }\n        }\n        if (par[t] == -1) break;\n        long long b = LLONG_MAX;\n        for (int v = t; v != s; v = par[v]) b = min(b, cap[pedge[v]]);\n        for (int v = t; v != s; v = par[v]) { cap[pedge[v]] -= b; cap[pedge[v]^1] += b; }\n        flow += b;\n    }\n    out << flow << \"\\n\";\n}\n";
W["hsga-p9-match"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int L, R, m; in >> L >> R >> m;\n    vector<vector<int>> cand(L + 1);\n    for (int i = 0; i < m; ++i) { int u, v; in >> u >> v; cand[u].push_back(v); }\n    // WRONG: greedy \u2014 each left node takes its first free right neighbor.\n    vector<char> usedR(R + 1, 0);\n    long long match = 0;\n    for (int u = 1; u <= L; ++u) {\n        for (int v : cand[u]) {\n            if (!usedR[v]) { usedR[v] = 1; ++match; break; }\n        }\n    }\n    out << match << \"\\n\";\n}\n";
