W["hsga-p9-dinic"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <queue>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n, m, s, t; in >> n >> m >> s >> t;\n    vector<long long> cap(2 * m, 0);\n    vector<vector<int>> g(n + 1);\n    vector<int> to(2 * m, 0);\n    for (int i = 0; i < m; ++i) {\n        int u, v; long long c; in >> u >> v >> c;\n        to[2*i] = v; cap[2*i] = c; g[u].push_back(2*i);\n        to[2*i+1] = u; cap[2*i+1] = 0; g[v].push_back(2*i+1);\n    }\n    long long flow = 0;\n    while (true) {\n        vector<int> par(n + 1, -1), pedge(n + 1, -1);\n        par[s] = s;\n        queue<int> q; q.push(s);\n        while (!q.empty() && par[t] == -1) {\n            int u = q.front(); q.pop();\n            for (int e : g[u]) {\n                if (cap[e] > 0 && par[to[e]] == -1) {\n                    par[to[e]] = u; pedge[to[e]] = e; q.push(to[e]);\n                }\n            }\n        }\n        if (par[t] == -1) break;\n        long long b = LLONG_MAX;\n        for (int v = t; v != s; v = par[v]) b = min(b, cap[pedge[v]]);\n        // push ONE unit per round (wrong: bottleneck split into unit pushes)\n        b = 1;\n        for (int v = t; v != s; v = par[v]) { cap[pedge[v]] -= b; cap[pedge[v]^1] += b; }\n        flow += b;\n    }\n    out << flow << \"\\n\";\n}\n";
R["hsga-cp-m10-digit"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    long long L, R; int K;\n    auto cntExact = [](long long N, int K) -> long long {\n        // count x in [0, N] with digit sum exactly K (leading zeros OK \u2014\n        // the all-zero number is the only collision, and it only lands in\n        // K = 0 where we compensate in the caller).\n        if (N < 0) return 0;\n        string s = to_string(N);\n        int n = s.size();\n        // dp[i][rem][tight]: after choosing i digits, digit-sum budget left\n        // = rem. Use iterative DP with rem <= 162.\n        static long long dp[2][2][165];\n        int cur = 0;\n        memset(dp, 0, sizeof(dp));\n        dp[cur][1][K] = 1;   // tight, full budget\n        for (int i = 0; i < n; ++i) {\n            int nxt = cur ^ 1;\n            memset(dp[nxt], 0, sizeof(dp[nxt]));\n            int lim = s[i] - '0';\n            for (int t2 = 0; t2 < 2; ++t2) {\n                int maxd = t2 ? lim : 9;\n                for (int rem = 0; rem <= K; ++rem) {\n                    long long v = dp[cur][t2][rem];\n                    if (!v) continue;\n                    for (int d = 0; d <= min(maxd, rem); ++d) {\n                        dp[nxt][t2 && d == maxd][rem - d] += v;\n                    }\n                }\n            }\n            cur = nxt;\n        }\n        long long total = dp[cur][0][0] + dp[cur][1][0];\n        return total;\n    };\n    while (in >> L >> R >> K) {\n        long long ans = cntExact(R, K) - cntExact(L - 1, K);\n        if (K == 0) ans = 0;   // no positive number has digit sum 0\n        out << ans << \"\\n\";\n    }\n}\n";
W["hsga-cp-m10-digit"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    long long L, R; int K;\n    auto cntExact = [](long long N, int K) -> long long {\n        if (N < 0) return 0;\n        string s = to_string(N);\n        int n = s.size();\n        static long long dp[2][2][165];\n        int cur = 0;\n        memset(dp, 0, sizeof(dp));\n        dp[cur][1][K] = 1;\n        for (int i = 0; i < n; ++i) {\n            int nxt = cur ^ 1;\n            memset(dp[nxt], 0, sizeof(dp[nxt]));\n            int lim = s[i] - '0';\n            for (int t2 = 0; t2 < 2; ++t2) {\n                int maxd = t2 ? lim : 9;\n                for (int rem = 0; rem <= K; ++rem) {\n                    long long v = dp[cur][t2][rem];\n                    if (!v) continue;\n                    for (int d = 0; d <= min(maxd, rem); ++d) {\n                        // WRONG: dp[nxt][0]... drops tight on every d\n                        dp[nxt][0][rem - d] += v;\n                    }\n                }\n            }\n            cur = nxt;\n        }\n        long long total = dp[cur][0][0] + dp[cur][1][0];\n        return total;\n    };\n    while (in >> L >> R >> K) {\n        long long ans = cntExact(R, K) - cntExact(L - 1, K);\n        if (K == 0) ans = 0;\n        out << ans << \"\\n\";\n    }\n}\n";
R["hsga-p10-div3"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s; in >> s;            // we count [1, N] via digit DP on N's digits\n    // input is a single N; count x in [1, N] with digit sum divisible by 3\n    // (see challenge statement: single-boundary form, L = 1).\n    int n = s.size();\n    // dp over positions with remainder state; free positions use closed\n    // counts per remainder via 3x3 transition tables, tight walk by hand.\n    static const long long C10[19] = {1,10,100,1000,10000,100000,1000000,\n        10000000,100000000,1000000000,10000000000LL,100000000000LL,\n        1000000000000LL,10000000000000LL,100000000000000LL,\n        1000000000000000LL,10000000000000000LL,100000000000000000LL,\n        1000000000000000000LL};\n    // free-state DP: cnt[k] = number of length-k free suffix strings with\n    // digit sum % 3 == k; iterate one digit at a time.\n    long long f0 = 1, f1 = 0, f2 = 0;   // remainder buckets for the suffix\n    long long c0 = 1, c1 = 0, c2 = 0;   // counting arrays per remainder\n    long long dp0 = 1, dp1 = 0, dp2 = 0;  // dp[r] = ways to have sum%3==r\n    // We do the classic \"sum over all lengths\" trick: answer(N) =\n    // sum over prefix positions of (ways for prefix with rem r) x\n    // (ways for free suffix making total rem 0), excluding empties.\n    long long ans = 0;\n    long long pr0 = 1, pr1 = 0, pr2 = 0;  // prefix remainder buckets incl. empty prefix\n    int L = n;\n    // suffix tables: suf[k][r] = # of length-k strings (digits 0..9 each,\n    // leading zeros fine) with digit sum % 3 == r\n    // compute iteratively\n    vector<array<long long,3>> suf(n + 1);\n    suf[0] = {1, 0, 0};\n    for (int k = 1; k <= n; ++k) {\n        // adding one free digit: r' = (r + d) % 3 over d in 0..9\n        // counts per residue for one digit: 0,3,6,9 -> 4 digits with r 0;\n        // 1,4,7 -> 3; 2,5,8 -> 3\n        long long a = 4, b = 3, c3 = 3;\n        suf[k][0] = suf[k-1][0] * a + suf[k-1][1] * c3 + suf[k-1][2] * b;\n        suf[k][1] = suf[k-1][0] * b + suf[k-1][1] * a + suf[k-1][2] * c3;\n        suf[k][2] = suf[k-1][0] * c3 + suf[k-1][1] * b + suf[k-1][2] * a;\n    }\n    long long pr[3] = {1, 0, 0};   // prefix buckets including empty prefix\n    long long running = 0;          // digit sum of the prefix so far\n    for (int i = 0; i < n; ++i) {\n        int dig = s[i] - '0';\n        int remLen = n - i - 1;\n        // enumerate digits d < dig at this position (tight breaks here)\n        for (int d = 0; d < dig; ++d) {\n            int nr = (running + d) % 3;\n            // free suffix of length remLen must satisfy (nr + sfx) % 3 == 0\n            // BUT leading-zero numbers with all-zero suffix + all-zero\n            // prefix would count 0; we subtract 1 at the end instead.\n            long long add = suf[remLen][(3 - nr) % 3];\n            if (nr == 0) ans += suf[remLen][0];\n            else if (nr == 1) ans += suf[remLen][2];\n            else ans += suf[remLen][1];\n        }\n        running = (running + dig) % 3;\n    }\n    // final tight number itself\n    if (running == 0) ans += 1;\n    // subtract the empty/zero number counted by the all-zero path\n    ans -= 1;\n    out << ans << \"\\n\";\n}\n";
W["hsga-p10-div3"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s; in >> s;\n    // WRONG: walks every integer up to N \u2014 astronomically slow for 1e18.\n    // Parse N, then loop i = 1..N testing digit sums. The load test's\n    // N = 999999999999999999 makes this run for years; even the \"small\"\n    // N = 1000000000000000000-1 case is hopeless. Keep it honest: the\n    // loop is real, and the sandbox's 0.5-CPU/10s budget kills it on the\n    // very first big test.\n    long long N = 0;\n    for (char c : s) N = N * 10 + (c - '0');\n    long long cnt = 0;\n    for (long long x = 1; x <= N; ++x) {\n        long long t = x, ds = 0;\n        while (t) { ds += t % 10; t /= 10; }\n        if (ds % 3 == 0) ++cnt;\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsga-p10-contains7"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    long long L, R; in >> L >> R;\n    // no7(N) = count of x in [0, N] containing no digit 7 (standard digit DP)\n    auto no7 = [](long long N) -> long long {\n        if (N < 0) return 0;\n        string s = to_string(N);\n        int n = s.size();\n        // tight walk: for each position, digits d < lim and d != 7 free\n        long long total = 0;\n        // free counts: number of length-k suffixes over digits {0..9}\\{7}\n        // = 9^k; the tight walk keeps a \"still tight\" chain.\n        // standard: for i in 0..n-1: for d in 0..lim-1, d != 7:\n        //   total += 9^(n-1-i) for the remaining free digits \u2014 but that\n        // counts suffixes with no 7, which is 9^(rem). Wait: 8 choices for\n        // this digit (d != 7, d < lim) times 9^rem for the rest.\n        long long p9[19]; p9[0] = 1;\n        for (int i = 1; i < 19; ++i) p9[i] = p9[i-1] * 9;\n        long long run = 0;\n        bool dead = false;\n        for (int i = 0; i < n && !dead; ++i) {\n            int lim = s[i] - '0';\n            for (int d = 0; d < lim; ++d) {\n                if (d == 7) continue;\n                total += p9[n - 1 - i];\n            }\n            if (lim == 7) { dead = true; break; }\n            run = run * 10 + lim;\n        }\n        if (!dead) total += 1;   // N itself has no 7\n        // the number 0 is included in this count (leading zeros) \u2014 it has\n        // no 7, consistent with counting [0, N].\n        return total;\n    };\n    long long ans = (R - no7(R)) - (L - 1 - no7(L - 1));\n    out << ans << \"\\n\";\n}\n";
W["hsga-p10-contains7"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    long long L, R; in >> L >> R;\n    // WRONG: scans the entire range checking each number's digits.\n    // On the load test [1, 1e18] this never terminates.\n    long long cnt = 0;\n    for (long long x = L; x <= R; ++x) {\n        long long t = x;\n        while (t) { if (t % 10 == 7) { ++cnt; break; } t /= 10; }\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsga-p10-exactk"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    long long L, R; int K;\n    auto cntExact = [](long long N, int K) -> long long {\n        // count x in [0, N] with digit sum exactly K (leading zeros OK \u2014\n        // the all-zero number is the only collision, and it only lands in\n        // K = 0 where we compensate in the caller).\n        if (N < 0) return 0;\n        string s = to_string(N);\n        int n = s.size();\n        // dp[i][rem][tight]: after choosing i digits, digit-sum budget left\n        // = rem. Use iterative DP with rem <= 162.\n        static long long dp[2][2][165];\n        int cur = 0;\n        memset(dp, 0, sizeof(dp));\n        dp[cur][1][K] = 1;   // tight, full budget\n        for (int i = 0; i < n; ++i) {\n            int nxt = cur ^ 1;\n            memset(dp[nxt], 0, sizeof(dp[nxt]));\n            int lim = s[i] - '0';\n            for (int t2 = 0; t2 < 2; ++t2) {\n                int maxd = t2 ? lim : 9;\n                for (int rem = 0; rem <= K; ++rem) {\n                    long long v = dp[cur][t2][rem];\n                    if (!v) continue;\n                    for (int d = 0; d <= min(maxd, rem); ++d) {\n                        dp[nxt][t2 && d == maxd][rem - d] += v;\n                    }\n                }\n            }\n            cur = nxt;\n        }\n        long long total = dp[cur][0][0] + dp[cur][1][0];\n        return total;\n    };\n    while (in >> L >> R >> K) {\n        long long ans = cntExact(R, K) - cntExact(L - 1, K);\n        if (K == 0) ans = 0;   // no positive number has digit sum 0\n        out << ans << \"\\n\";\n    }\n}\n";
W["hsga-p10-exactk"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <cstring>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    long long L, R; int K;\n    auto cntExact = [](long long N, int K) -> long long {\n        if (N < 0) return 0;\n        string s = to_string(N);\n        int n = s.size();\n        static long long dp[2][2][165];\n        int cur = 0;\n        memset(dp, 0, sizeof(dp));\n        dp[cur][1][K] = 1;\n        for (int i = 0; i < n; ++i) {\n            int nxt = cur ^ 1;\n            memset(dp[nxt], 0, sizeof(dp[nxt]));\n            int lim = s[i] - '0';\n            for (int t2 = 0; t2 < 2; ++t2) {\n                int maxd = t2 ? lim : 9;\n                for (int rem = 0; rem <= K; ++rem) {\n                    long long v = dp[cur][t2][rem];\n                    if (!v) continue;\n                    for (int d = 0; d <= min(maxd, rem); ++d) {\n                        // WRONG: dp[nxt][0]... drops tight on every d\n                        dp[nxt][0][rem - d] += v;\n                    }\n                }\n            }\n            cur = nxt;\n        }\n        long long total = dp[cur][0][0] + dp[cur][1][0];\n        return total;\n    };\n    while (in >> L >> R >> K) {\n        long long ans = cntExact(R, K) - cntExact(L - 1, K);\n        if (K == 0) ans = 0;\n        out << ans << \"\\n\";\n    }\n}\n";
R["hsga-cp-m11-merge"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    vector<long long> a(n + 1), pre(n + 1, 0);\n    for (int i = 1; i <= n; ++i) { in >> a[i]; pre[i] = pre[i-1] + a[i]; }\n    vector<vector<long long>> dp(n + 2, vector<long long>(n + 2, 0));\n    for (int L = 2; L <= n; ++L)\n        for (int i = 1; i + L - 1 <= n; ++i) {\n            int j = i + L - 1;\n            dp[i][j] = LLONG_MAX;\n            long long s = pre[j] - pre[i-1];\n            for (int k = i; k < j; ++k)\n                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] + s);\n        }\n    out << (n <= 1 ? 0LL : dp[1][n]) << \"\\n\";\n}\n";
W["hsga-cp-m11-merge"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: repeatedly merge the adjacent pair with the smallest sum \u2014\n    // locally cheap, globally wrong (e.g. [3,1,2,5]: merging 1,2 first is\n    // optimal; greedy might pick 3,1).\n    long long cost = 0;\n    while ((int)a.size() > 1) {\n        int bi = 0; long long bs = a[0] + a[1];\n        for (int i = 1; i + 1 < (int)a.size(); ++i)\n            if (a[i] + a[i+1] < bs) { bs = a[i] + a[i+1]; bi = i; }\n        a[bi] = bs;\n        a.erase(a.begin() + bi + 1);\n        cost += bs;\n    }\n    out << cost << \"\\n\";\n}\n";
R["hsga-p11-mcm"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    vector<long long> d(n + 1);\n    for (auto& x : d) in >> x;\n    vector<vector<long long>> dp(n + 2, vector<long long>(n + 2, 0));\n    for (int L = 2; L <= n; ++L)\n        for (int i = 1; i + L - 1 <= n; ++i) {\n            int j = i + L - 1;\n            dp[i][j] = LLONG_MAX;\n            for (int k = i; k < j; ++k)\n                dp[i][j] = min(dp[i][j],\n                               dp[i][k] + dp[k+1][j] + d[i-1]*d[k]*d[j]);\n        }\n    out << (n <= 1 ? 0LL : dp[1][n]) << \"\\n\";\n}\n";
W["hsga-p11-mcm"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    vector<long long> d(n + 1);\n    for (auto& x : d) in >> x;\n    // WRONG: recursive greedy \u2014 pick the k minimizing the CURRENT merge\n    // cost d[i-1]*d[k]*d[j], never revisiting. Fails on [10,30,5,60].\n    auto g = [&](auto&& self, int i, int j) -> long long {\n        if (j - i < 1) return 0;\n        long long best = LLONG_MAX; int bk = i;\n        for (int k = i; k < j; ++k) {\n            long long c = d[i-1]*d[k]*d[j];\n            if (c < best) { best = c; bk = k; }\n        }\n        return best + self(self, i, bk) + self(self, bk + 1, j);\n    };\n    out << (n <= 1 ? 0LL : g(g, 1, n)) << \"\\n\";\n}\n";
