R["hsga-p11-lps"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s;\n    while (in >> s) {\n        int n = s.size();\n        vector<vector<int>> dp(n, vector<int>(n, 0));\n        for (int i = n - 1; i >= 0; --i) {\n            dp[i][i] = 1;\n            for (int j = i + 1; j < n; ++j) {\n                if (s[i] == s[j])\n                    dp[i][j] = (i + 1 <= j - 1) ? dp[i+1][j-1] + 2 : 2;\n                else\n                    dp[i][j] = max(dp[i+1][j], dp[i][j-1]);\n            }\n        }\n        out << (n ? dp[0][n-1] : 0) << \"\\n\";\n    }\n}\n";
