R["hsga-cp-m12-distinct"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <set>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s;\n    while (in >> s) {\n        int n = s.size();\n        vector<int> sa(n), rnk(n), tmp(n);\n        for (int i = 0; i < n; ++i) { sa[i] = i; rnk[i] = s[i]; }\n        for (int k = 1; ; k <<= 1) {\n            auto cmp = [&](int a, int b) {\n                if (rnk[a] != rnk[b]) return rnk[a] < rnk[b];\n                int ra = a + k < n ? rnk[a + k] : -1;\n                int rb = b + k < n ? rnk[b + k] : -1;\n                return ra < rb;\n            };\n            sort(sa.begin(), sa.end(), cmp);\n            tmp[sa[0]] = 0;\n            for (int i = 1; i < n; ++i)\n                tmp[sa[i]] = tmp[sa[i-1]] + (cmp(sa[i-1], sa[i]) ? 1 : 0);\n            rnk = tmp;\n            if (rnk[sa[n-1]] == n - 1) break;\n            if (k >= n) break;\n        }\n        // Kasai LCP + total distinct = n(n+1)/2 - sum LCP\n        vector<int> lcp(n, 0), pos(n);\n        for (int i = 0; i < n; ++i) pos[sa[i]] = i;\n        int h2 = 0;\n        long long tot = (long long)n * (n + 1) / 2;\n        for (int i = 0; i < n; ++i) {\n            if (pos[i] > 0) {\n                int j = sa[pos[i] - 1];\n                while (i + h2 < n && j + h2 < n && s[i + h2] == s[j + h2]) ++h2;\n                lcp[pos[i]] = h2;\n                tot -= h2;\n                if (h2) --h2;\n            } else h2 = 0;\n        }\n        out << tot << \"\\n\";\n    }\n}\n";
W["hsga-cp-m12-distinct"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <set>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s;\n    while (in >> s) {\n        int n = s.size();\n        // WRONG: enumerate every substring into a set \u2014 O(n^2) strings of\n        // average length n/2: 2M strings x 1KB for n = 2000 \u2014 memory and\n        // time blow up.\n        set<string> st;\n        for (int i = 0; i < n; ++i)\n            for (int j = i + 1; j <= n; ++j)\n                st.insert(s.substr(i, j - i));\n        out << st.size() << \"\\n\";\n    }\n}\n";
R["hsga-p12-hashlen"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <set>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s; in >> s;\n    int q; in >> q;\n    const long long M1 = 1000000007LL, B = 131;\n    int n = s.size();\n    vector<long long> h(n + 1, 0), p(n + 1, 1);\n    for (int i = 0; i < n; ++i) {\n        h[i+1] = (h[i] * B + s[i]) % M1;\n        p[i+1] = (p[i] * B) % M1;\n    }\n    auto sub = [&](int i, int L) {\n        return (h[i+L] - h[i] * p[L] % M1 + M1) % M1;\n    };\n    while (q--) {\n        int L; in >> L;\n        if (L > n) { out << 0 << \"\\n\"; continue; }\n        vector<long long> v;\n        v.reserve(n - L + 1);\n        for (int i = 0; i + L <= n; ++i) v.push_back(sub(i, L));\n        sort(v.begin(), v.end());\n        long long d = unique(v.begin(), v.end()) - v.begin();\n        out << d << \"\\n\";\n    }\n}\n";
W["hsga-p12-hashlen"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <set>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s; in >> s;\n    int q; in >> q;\n    const long long M1 = 1000000007LL, B = 131;\n    int n = s.size();\n    vector<long long> h(n + 1, 0);\n    for (int i = 0; i < n; ++i) h[i+1] = (h[i] * B + s[i]) % M1;\n    while (q--) {\n        int L; in >> L;\n        if (L > n) { out << 0 << \"\\n\"; continue; }\n        // WRONG: compares (h[i+L] - h[i]) UNSCALED - different positions of\n        // the same substring produce different values, so distinct counts\n        // come out wrong on any non-constant string.\n        vector<long long> v;\n        for (int i = 0; i + L <= n; ++i)\n            v.push_back((h[i+L] - h[i] + M1) % M1);\n        sort(v.begin(), v.end());\n        long long d = unique(v.begin(), v.end()) - v.begin();\n        out << d << \"\\n\";\n    }\n}\n";
R["hsga-p12-zarray"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <set>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s; in >> s;\n    int n = s.size();\n    vector<int> z(n, 0);\n    if (n) z[0] = n;\n    for (int i = 1, l = 0, r = 0; i < n; ++i) {\n        if (i < r) z[i] = min(r - i, z[i - l]);\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) ++z[i];\n        if (i + z[i] > r) { l = i; r = i + z[i]; }\n    }\n    for (int i = 0; i < n; ++i) { if (i) out << ' '; out << z[i]; }\n    out << \"\\n\";\n}\n";
