R["hsga-cp-m13-crt"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // CRT: x = a (mod n), x = b (mod m), gcd(n, m) = 1.\n    // x = a + n*t, t = (b - a) * n^(-1) (mod m) via EXTENDED EUCLID\n    // (m need not be prime).\n    int q; in >> q;\n    auto inv = [](long long a, long long m) {\n        long long r0 = m, r1 = a % m, s0 = 0, s1 = 1;\n        while (r1) {\n            long long qf = r0 / r1;\n            long long tr = r0 - qf * r1; r0 = r1; r1 = tr;\n            long long ts = s0 - qf * s1; s0 = s1; s1 = ts;\n        }\n        return ((s0 % m) + m) % m;  // inverse of a mod m\n    };\n    while (q--) {\n        long long a, n, b, m; in >> a >> n >> b >> m;\n        long long t = ((b - a) % m + m) % m;\n        t = t * inv(n, m) % m;\n        long long x = (a + n * t) % (n * m);\n        out << x << \"\\n\";\n    }\n}\n";
