R["hsga-p13-binom"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    const long long P = 1000000007LL, N = 1000001;\n    static long long f[1000001], inv[1000001];\n    if (f[0] == 0) {\n        f[0] = 1;\n        for (long long i = 1; i < N; ++i) f[i] = f[i-1] * i % P;\n        auto pw = [](long long a, long long e) {\n            long long r = 1; a %= P;\n            while (e) { if (e & 1) r = r * a % P; a = a * a % P; e >>= 1; }\n            return r;\n        };\n        inv[N-1] = pw(f[N-1], P - 2);\n        for (long long i = N - 1; i >= 1; --i) inv[i-1] = inv[i] * i % P;\n    }\n    int q; in >> q;\n    while (q--) {\n        long long n, r; in >> n >> r;\n        if (r < 0 || r > n) { out << 0 << \"\\n\"; continue; }\n        out << f[n] * inv[r] % P * inv[n-r] % P << \"\\n\";\n    }\n}\n";
