R["hsga-cp-m15-hull"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Checkpoint: convex hull + doubled area on mixed polygons\n    int n; in >> n;\n    vector<pair<long long, long long>> p(n);\n    for (auto& [x, y] : p) in >> x >> y;\n    sort(p.begin(), p.end());\n    p.erase(unique(p.begin(), p.end()), p.end());\n    int m = p.size();\n    if (m == 1) { out << 0 << \"\\n\"; return; }\n    if (m == 2) {\n        long long a = llabs(p[0].first * p[1].second - p[0].second * p[1].first);\n        out << a << \"\\n\";\n        return;\n    }\n    vector<pair<long long, long long>> h(2 * m);\n    int k = 0;\n    for (int i = 0; i < m; ++i) {\n        while (k >= 2) {\n            long long cr = (h[k-1].first - h[k-2].first) * (p[i].second - h[k-2].second)\n                         - (h[k-1].second - h[k-2].second) * (p[i].first - h[k-2].first);\n            if (cr <= 0) --k; else break;\n        }\n        h[k++] = p[i];\n    }\n    for (int i = m - 2, t = k + 1; i >= 0; --i) {\n        while (k >= t) {\n            long long cr = (h[k-1].first - h[k-2].first) * (p[i].second - h[k-2].second)\n                         - (h[k-1].second - h[k-2].second) * (p[i].first - h[k-2].first);\n            if (cr <= 0) --k; else break;\n        }\n        h[k++] = p[i];\n    }\n    long long a = 0;\n    for (int i = 0; i < k - 1; ++i) {\n        int j = (i + 1) % (k - 1);\n        a += h[i].first * h[j].second - h[j].first * h[i].second;\n    }\n    out << llabs(a) << \"\\n\";\n}\n";
W["hsga-cp-m15-hull"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <cmath>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: shoelace over the INPUT order (not the hull) \u2014 for polygons\n    // given in arbitrary point order the answer is wrong (self-intersecting\n    // walk cancels area).\n    int n; in >> n;\n    vector<pair<long long, long long>> p(n);\n    for (auto& [x, y] : p) in >> x >> y;\n    long long a = 0;\n    for (int i = 0; i < n; ++i) {\n        int j = (i + 1) % n;\n        a += p[i].first * p[j].second - p[j].first * p[i].second;\n    }\n    out << llabs(a) << \"\\n\";\n}\n";
R["hsga-p16-subrange"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Count subarrays with sum in [L, R] over positive values:\n    // prefix sums are increasing; for each j count i < j with\n    // P[j]-R <= P[i] <= P[j]-L via binary search.\n    int n; long long L, R; in >> n >> L >> R;\n    vector<long long> P(n + 1, 0);\n    for (int i = 1; i <= n; ++i) {\n        long long x; in >> x;\n        P[i] = P[i-1] + x;\n    }\n    long long cnt = 0;\n    for (int j = 0; j <= n; ++j) {\n        long long lo = lower_bound(P.begin(), P.begin() + j, P[j] - R) - P.begin();\n        long long hi = upper_bound(P.begin(), P.begin() + j, P[j] - L) - P.begin();\n        cnt += hi - lo;\n    }\n    out << cnt << \"\\n\";\n}\n";
