R["hsga-p16-inv"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Count inversions: coordinate-compress, Fenwick walk from the right.\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    vector<long long> s(a);\n    sort(s.begin(), s.end());\n    s.erase(unique(s.begin(), s.end()), s.end());\n    int m = s.size();\n    auto rankof = [&](long long v) {\n        return int(lower_bound(s.begin(), s.end(), v) - s.begin()) + 1;\n    };\n    vector<int> fen(m + 1, 0);\n    auto upd = [&](int i) {\n        for (; i <= m; i += i & -i) ++fen[i];\n    };\n    auto qry = [&](int i) {\n        long long t = 0;\n        for (; i > 0; i -= i & -i) t += fen[i];\n        return t;\n    };\n    long long inv = 0;\n    for (int i = n - 1; i >= 0; --i) {\n        int r = rankof(a[i]);\n        inv += qry(r - 1);\n        upd(r);\n    }\n    out << inv << \"\\n\";\n}\n";
W["hsga-p16-inv"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: merge-sort inversion count that adds (mid - i) on EQUAL\n    // elements \u2014 counts equal pairs as inversions. With distinct values the\n    // answer is right; with duplicates it overcounts.\n    int n; in >> n;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    long long inv = 0;\n    vector<long long> buf(n);\n    function<void(int, int)> ms = [&](int lo, int hi) {\n        if (hi - lo <= 1) return;\n        int mid = (lo + hi) / 2;\n        ms(lo, mid); ms(mid, hi);\n        int i = lo, j = mid, k = lo;\n        while (i < mid && j < hi) {\n            if (a[j] <= a[i]) { buf[k++] = a[j++]; inv += mid - i; }  // <= counts equals \u2014 BUG\n            else buf[k++] = a[i++];\n        }\n        while (i < mid) buf[k++] = a[i++];\n        while (j < hi) buf[k++] = a[j++];\n        for (int t = lo; t < hi; ++t) a[t] = buf[t];\n    };\n    ms(0, n);\n    out << inv << \"\\n\";\n}\n";
R["hsga-p16-rooms"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Minimum rooms: sort by start, min-heap of end times, pop expired.\n    int n; in >> n;\n    vector<pair<long long, long long>> iv(n);\n    for (auto& [s, e] : iv) in >> s >> e;\n    sort(iv.begin(), iv.end());\n    priority_queue<long long, vector<long long>, greater<long long>> h;\n    int best = 0;\n    for (auto& [s, e] : iv) {\n        while (!h.empty() && h.top() <= s) h.pop();\n        h.push(e);\n        best = max(best, (int)h.size());\n    }\n    out << best << \"\\n\";\n}\n";
W["hsga-p16-rooms"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: treats intervals [s1,e1) and [e1,e2) as OVERLAPPING (uses\n    // h.top() < s instead of <=). Answers blow up on back-to-back chains.\n    int n; in >> n;\n    vector<pair<long long, long long>> iv(n);\n    for (auto& [s, e] : iv) in >> s >> e;\n    sort(iv.begin(), iv.end());\n    priority_queue<long long, vector<long long>, greater<long long>> h;\n    int best = 0;\n    for (auto& [s, e] : iv) {\n        while (!h.empty() && h.top() < s) h.pop();  // strict: off by one\n        h.push(e);\n        best = max(best, (int)h.size());\n    }\n    out << best << \"\\n\";\n}\n";
R["hsga-cp-m16-maxmin"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Binary search on the answer + greedy feasibility.\n    int n; long long k; in >> n >> k;\n    vector<long long> p(n);\n    for (auto& x : p) in >> x;\n    sort(p.begin(), p.end());\n    long long lo = 0, hi = p[n-1] - p[0];\n    auto feasible = [&](long long d) {\n        long long c = 1, last = p[0];\n        for (int i = 1; i < n; ++i) {\n            if (p[i] - last >= d) { ++c; last = p[i]; }\n        }\n        return c >= k;\n    };\n    while (lo < hi) {\n        long long mid = (lo + hi + 1) / 2;\n        if (feasible(mid)) lo = mid;\n        else hi = mid - 1;\n    }\n    out << lo << \"\\n\";\n}\n";
W["hsga-cp-m16-maxmin"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: feasibility uses > d (strictly greater) instead of >= d \u2014\n    // the greedy places one fewer point whenever a gap is EXACTLY d, so\n    // the answer comes out one notch low on exact-gap data.\n    int n; long long k; in >> n >> k;\n    vector<long long> p(n);\n    for (auto& x : p) in >> x;\n    sort(p.begin(), p.end());\n    long long lo = 0, hi = p[n-1] - p[0];\n    auto feasible = [&](long long d) {\n        long long c = 1, last = p[0];\n        for (int i = 1; i < n; ++i) {\n            if (p[i] - last > d) { ++c; last = p[i]; }  // off-by-one\n        }\n        return c >= k;\n    };\n    while (lo < hi) {\n        long long mid = (lo + hi + 1) / 2;\n        if (feasible(mid)) lo = mid;\n        else hi = mid - 1;\n    }\n    out << lo << \"\\n\";\n}\n";
R["hsga-p17-pairs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Count unordered pairs with a[i] + a[j] == target. Values near 2e9\n    // force 64-bit sums.\n    int n; long long target; in >> n >> target;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    long long cnt = 0;\n    int i = 0, j = n - 1;\n    while (i < j) {\n        long long s = a[i] + a[j];\n        if (s < target) ++i;\n        else if (s > target) --j;\n        else {\n            if (a[i] == a[j]) {\n                long long c = j - i + 1;\n                cnt += c * (c - 1) / 2;\n                break;\n            }\n            long long ci = 1, cj = 1;\n            while (i + 1 < j && a[i+1] == a[i]) { ++i; ++ci; }\n            while (j - 1 > i && a[j-1] == a[j]) { --j; ++cj; }\n            cnt += ci * cj;\n            ++i; --j;\n        }\n    }\n    out << cnt << \"\\n\";\n}\n";
W["hsga-p17-pairs"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: sums in 32-bit int \u2014 a[i]+a[j] with values near 2e9 overflows\n    // and wraps negative; the two-pointer then walks off. Classic contest bug.\n    int n; long long target; in >> n >> target;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    sort(a.begin(), a.end());\n    long long cnt = 0;\n    int i = 0, j = n - 1;\n    while (i < j) {\n        int s = (int)(a[i] + a[j]);  // overflow here\n        if (s < target) ++i;\n        else if (s > target) --j;\n        else { cnt += 1; ++i; --j; }\n    }\n    out << cnt << \"\\n\";\n}\n";
R["hsga-p17-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Subtree sizes on a rooted forest given as parent[] (parent[1] = 0).\n    // ITERATIVE post-order: bamboo of 2e5 nodes kills recursive DFS.\n    int n; in >> n;\n    vector<int> par(n + 1, 0);\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) {\n        in >> par[v];\n        ch[par[v]].push_back(v);\n    }\n    vector<long long> sz(n + 1, 1);\n    // iterative post-order via explicit stack of (node, child-index)\n    vector<pair<int, int>> st;\n    st.push_back({1, 0});\n    while (!st.empty()) {\n        int v = st.back().first;\n        int idx = st.back().second;\n        if (idx < (int)ch[v].size()) {\n            ++st.back().second;\n            st.push_back({ch[v][idx], 0});\n        } else {\n            if (par[v]) sz[par[v]] += sz[v];\n            st.pop_back();\n        }\n    }\n    int q; in >> q;\n    while (q--) {\n        int v; in >> v;\n        out << sz[v] << \"\\n\";\n    }\n}\n";
W["hsga-p17-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: recursive DFS \u2014 the bamboo makes recursion depth 200000,\n    // smashing the stack (runtime error) long before answering.\n    int n; in >> n;\n    vector<int> par(n + 1, 0);\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) {\n        in >> par[v];\n        ch[par[v]].push_back(v);\n    }\n    vector<long long> sz(n + 1, 1);\n    function<void(int)> dfs = [&](int v) {\n        for (int c : ch[v]) { dfs(c); sz[v] += sz[c]; }\n    };\n    dfs(1);\n    int q; in >> q;\n    while (q--) {\n        int v; in >> v;\n        out << sz[v] << \"\\n\";\n    }\n}\n";
R["hsga-p17-diff"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Difference array with the cancel at r+1 \u2014 answer checksum of the\n    // final array after all range-adds.\n    int n; int q; in >> n >> q;\n    vector<long long> d(n + 2, 0);\n    for (int t = 0; t < q; ++t) {\n        long long l, r, v; in >> l >> r >> v;\n        d[l] += v;\n        d[r + 1] -= v;\n    }\n    long long cur = 0, cs = 0;\n    const long long P = 1000000007LL;\n    for (int i = 1; i <= n; ++i) {\n        cur += d[i];\n        cs = (cs + cur) % P;\n    }\n    out << ((cs % P) + P) % P << \"\\n\";\n}\n";
W["hsga-p17-diff"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // WRONG: cancels at r instead of r+1 \u2014 every range is one short on the\n    // right end; the checksum drifts.\n    int n; int q; in >> n >> q;\n    vector<long long> d(n + 2, 0);\n    for (int t = 0; t < q; ++t) {\n        long long l, r, v; in >> l >> r >> v;\n        d[l] += v;\n        d[r] -= v;  // off by one: should be r+1\n    }\n    long long cur = 0, cs = 0;\n    const long long P = 1000000007LL;\n    for (int i = 1; i <= n; ++i) {\n        cur += d[i];\n        cs = (cs + cur) % P;\n    }\n    out << ((cs % P) + P) % P << \"\\n\";\n}\n";
