R["hsga-cp18-scc"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Iterative Kosaraju \u2014 largest strongly connected component.\n    int n; long long m; in >> n >> m;\n    vector<vector<int>> g(n + 1), gr(n + 1);\n    for (long long e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n        gr[v].push_back(u);\n    }\n    vector<char> vis(n + 1, 0);\n    vector<int> order;\n    order.reserve(n);\n    for (int s = 1; s <= n; ++s) {\n        if (vis[s]) continue;\n        vector<pair<int, int>> st;\n        st.push_back({s, 0});\n        vis[s] = 1;\n        while (!st.empty()) {\n            int v = st.back().first;\n            int i = st.back().second;\n            if (i < (int)g[v].size()) {\n                ++st.back().second;\n                int u = g[v][i];\n                if (!vis[u]) { vis[u] = 1; st.push_back({u, 0}); }\n            } else {\n                order.push_back(v);\n                st.pop_back();\n            }\n        }\n    }\n    vector<int> comp(n + 1, 0);\n    int c = 0;\n    vector<int> sz(1, 0);\n    for (int i = n - 1; i >= 0; --i) {\n        int s = order[i];\n        if (comp[s]) continue;\n        ++c;\n        sz.push_back(0);\n        comp[s] = c;\n        vector<int> st(1, s);\n        while (!st.empty()) {\n            int v = st.back();\n            st.pop_back();\n            ++sz[c];\n            for (int u : gr[v]) if (!comp[u]) { comp[u] = c; st.push_back(u); }\n        }\n    }\n    int best = 0;\n    for (int i = 1; i <= c; ++i) best = max(best, sz[i]);\n    out << best << \"\\n\";\n}\n";
W["hsga-cp18-scc"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; long long m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    for (long long e = 0; e < m; ++e) {\n        int u, v; in >> u >> v;\n        g[u].push_back(v);\n    }\n    // WRONG: labels \"components\" by forward reach from each unvisited\n    // node \u2014 a cycle plus everything it can reach becomes one component.\n    vector<char> vis(n + 1, 0);\n    int best = 0;\n    for (int s = 1; s <= n; ++s) {\n        if (vis[s]) continue;\n        vector<int> st(1, s);\n        vis[s] = 1;\n        int cnt = 0;\n        while (!st.empty()) {\n            int v = st.back();\n            st.pop_back();\n            ++cnt;\n            for (int u : g[v]) if (!vis[u]) { vis[u] = 1; st.push_back(u); }\n        }\n        best = max(best, cnt);\n    }\n    out << best << \"\\n\";\n}\n";
