W["hsga-cp18-timeline"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; long long k; in >> n >> k;\n    vector<int> par(n + 1);\n    for (int i = 1; i <= n; ++i) par[i] = i;\n    std::function<int(int)> find = [&](int x) {\n        while (par[x] != x) { par[x] = par[par[x]]; x = par[x]; }\n        return x;\n    };\n    for (long long t = 0; t < k; ++t) {\n        int u, v; in >> u >> v;\n        int ru = find(u), rv = find(v);\n        if (ru != rv) par[ru] = rv;\n        // WRONG: recounts components by scanning every node's root \u2014\n        // O(n) per op; 2e5 ops on n = 2e5 is 4e10 steps.\n        int comps = 0;\n        for (int i = 1; i <= n; ++i) if (find(i) == i) ++comps;\n        out << comps << \"\\n\";\n    }\n}\n";
R["hsga-p18-ords"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // order statistics: BIT over value range 1..1e6 + k-th descent\n    const int MX = 1000000;\n    int q; in >> q;\n    vector<int> fen(MX + 1, 0);\n    auto upd = [&](int i, int d) { for (; i <= MX; i += i & (-i)) fen[i] += d; };\n    auto kth = [&](int k) {\n        int pos = 0;\n        for (int pw = 1 << 19; pw; pw >>= 1) {\n            int np = pos + pw;\n            if (np <= MX && fen[np] < k) { pos = np; k -= fen[np]; }\n        }\n        return pos + 1;\n    };\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { int x; in >> x; upd(x, 1); }\n        else { int k; in >> k; out << kth(k) << \"\\n\"; }\n    }\n}\n";
W["hsga-p18-ords"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int q; in >> q;\n    vector<long long> a;\n    a.reserve(200005);\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { long long x; in >> x; a.push_back(x); }\n        else {\n            int k; in >> k;\n            // WRONG: re-sorts the whole vector for every k-th query \u2014\n            // 1e5 sorts of up to 2e5 elements is far beyond the budget.\n            vector<long long> b = a;\n            sort(b.begin(), b.end());\n            out << b[k - 1] << \"\\n\";\n        }\n    }\n}\n";
R["hsga-p18-ords"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // order statistics: BIT over value range 1..1e6 + k-th descent\n    const int MX = 1000000;\n    int q; in >> q;\n    vector<int> fen(MX + 1, 0);\n    auto upd = [&](int i, int d) { for (; i <= MX; i += i & (-i)) fen[i] += d; };\n    auto kth = [&](int k) {\n        int pos = 0;\n        for (int pw = 1 << 19; pw; pw >>= 1) {\n            int np = pos + pw;\n            if (np <= MX && fen[np] < k) { pos = np; k -= fen[np]; }\n        }\n        return pos + 1;\n    };\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { int x; in >> x; upd(x, 1); }\n        else { int k; in >> k; out << kth(k) << \"\\n\"; }\n    }\n}\n";
