R["hsga-p18-tolls"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; long long m; in >> n >> m;\n    vector<vector<pair<int, long long>>> g(n + 1);\n    for (long long e = 0; e < m; ++e) {\n        int u, v; long long w; in >> u >> v >> w;\n        g[u].push_back({v, w});\n    }\n    vector<long long> dist(n + 1, -1);\n    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> pq;\n    dist[1] = 0;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        auto [d, v] = pq.top();\n        pq.pop();\n        if (dist[v] != -1 && d > dist[v]) continue;\n        for (auto& [u, w] : g[v]) {\n            long long nd = d + w;\n            if (dist[u] == -1 || nd < dist[u]) { dist[u] = nd; pq.push({nd, u}); }\n        }\n    }\n    out << dist[n] << \"\\n\";\n}\n";
W["hsga-p18-tolls"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; long long m; in >> n >> m;\n    vector<vector<int>> g(n + 1);\n    for (long long e = 0; e < m; ++e) {\n        int u, v; long long w; in >> u >> v >> w;\n        g[u].push_back(v);\n    }\n    // WRONG: BFS counts HOPS, not tolls \u2014 the first layer to reach n\n    // wins regardless of how expensive its edges are.\n    vector<int> dist(n + 1, -1);\n    vector<int> q(1, 1);\n    dist[1] = 0;\n    for (int h = 0; h < (int)q.size(); ++h) {\n        int v = q[h];\n        for (int u : g[v]) if (dist[u] == -1) { dist[u] = dist[v] + 1; q.push_back(u); }\n    }\n    out << dist[n] << \"\\n\";\n}\n";
