R["hsga-cp19-pathsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Node-weighted path sums via LCA: rd[x] = weight sum root..x.\n    int n; in >> n;\n    vector<int> par(n + 1, 0), dep(n + 1, 0);\n    vector<long long> w(n + 1, 0), rd(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    for (int v = 1; v <= n; ++v) in >> w[v];\n    const int LOG = 18;\n    vector<vector<int>> up(LOG, vector<int>(n + 1, 0));\n    up[0][1] = 1;  // root's parent is itself\n    for (int v = 2; v <= n; ++v) {\n        dep[v] = dep[par[v]] + 1;\n        rd[v] = rd[par[v]] + w[v];\n        up[0][v] = par[v];\n    }\n    rd[1] = w[1];\n    for (int k = 1; k < LOG; ++k)\n        for (int v = 1; v <= n; ++v)\n            up[k][v] = up[k - 1][up[k - 1][v]];\n    auto lca = [&](int a, int b) {\n        if (dep[a] < dep[b]) swap(a, b);\n        int d = dep[a] - dep[b];\n        for (int k = 0; k < LOG; ++k)\n            if (d >> k & 1) a = up[k][a];\n        if (a == b) return a;\n        for (int k = LOG - 1; k >= 0; --k)\n            if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }\n        return up[0][a];\n    };\n    int q; in >> q;\n    while (q--) {\n        int u, v; in >> u >> v;\n        int l = lca(u, v);\n        long long ans = rd[u] + rd[v] - 2 * rd[l] + w[l];\n        out << ans << \"\\n\";\n    }\n}\n";
W["hsga-cp19-pathsum"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    vector<int> par(n + 1, 0), dep(n + 1, 0);\n    vector<long long> w(n + 1, 0), rd(n + 1, 0);\n    for (int v = 2; v <= n; ++v) in >> par[v];\n    for (int v = 1; v <= n; ++v) in >> w[v];\n    for (int v = 2; v <= n; ++v) {\n        dep[v] = dep[par[v]] + 1;\n        rd[v] = rd[par[v]] + w[v];\n    }\n    rd[1] = w[1];\n    int q; in >> q;\n    while (q--) {\n        int u, v; in >> u >> v;\n        // WRONG: per-query parent climb \u2014 correct answers, O(depth) each;\n        // a 200000-node bamboo with 200000 deep queries is 4e10 steps.\n        int a = u, b = v;\n        while (dep[a] > dep[b]) a = par[a];\n        while (dep[b] > dep[a]) b = par[b];\n        while (a != b) { a = par[a]; b = par[b]; }\n        out << rd[u] + rd[v] - 2 * rd[a] + w[a] << \"\\n\";\n    }\n}\n";
