R["hsga-cp19-period"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Shortest period = n - fail[n] (KMP failure function).\n    string s; in >> s;\n    int n = (int)s.size();\n    vector<int> f(n + 1, 0);\n    for (int i = 1; i < n; ++i) {\n        int j = f[i];\n        while (j && s[i] != s[j]) j = f[j];\n        if (s[i] == s[j]) ++j;\n        f[i + 1] = j;\n    }\n    out << (n - f[n]) << \"\\n\";\n}\n";
W["hsga-cp19-period"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s; in >> s;\n    int n = (int)s.size();\n    // WRONG: only periods that DIVIDE n are checked \u2014 \"abcabca\" has\n    // period 3 but n = 7, so the W reports 7.\n    for (int d = 1; d <= n; ++d) {\n        if (n % d != 0) continue;\n        bool ok = true;\n        for (int i = d; i < n && ok; ++i) ok = (s[i] == s[i - d]);\n        if (ok) { out << d << \"\\n\"; return; }\n    }\n    out << n << \"\\n\";\n}\n";
