R["hsga-cp19-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // dp[v] = max edges from v down into its subtree (iterative postorder).\n    int n; in >> n;\n    vector<int> par(n + 1, 0);\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) { in >> par[v]; ch[par[v]].push_back(v); }\n    vector<int> order;\n    order.reserve(n);\n    vector<int> st(1, 1);\n    while (!st.empty()) {\n        int v = st.back();\n        st.pop_back();\n        order.push_back(v);\n        for (int c : ch[v]) st.push_back(c);\n    }\n    vector<int> dp(n + 1, 0);\n    for (int i = n - 1; i >= 0; --i) {\n        int v = order[i];\n        int best = 0;\n        for (int c : ch[v]) best = max(best, dp[c] + 1);\n        dp[v] = best;\n        out << dp[v] << \"\\n\";\n    }\n}\n";
W["hsga-cp19-subtree"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    vector<int> par(n + 1, 0), dep(n + 1, 0);\n    for (int v = 2; v <= n; ++v) { in >> par[v]; dep[v] = dep[par[v]] + 1; }\n    // WRONG: prints the GLOBAL tree height for every node \u2014 the per-node\n    // subtree invariant is lost; any tree with differing answers breaks it.\n    int height = 0;\n    for (int v = 1; v <= n; ++v) height = max(height, dep[v]);\n    for (int v = 1; v <= n; ++v) out << height << \"\\n\";\n}\n";
