R["hsga-cp19-motif"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // KMP per pattern counts OVERLAPPING occurrences.\n    int n; in >> n;\n    string s; in >> s;\n    int q; in >> q;\n    while (q--) {\n        string p; in >> p;\n        int m = (int)p.size();\n        vector<int> f(m + 1, 0);\n        for (int i = 1; i < m; ++i) {\n            int j = f[i];\n            while (j && p[i] != p[j]) j = f[j];\n            if (p[i] == p[j]) ++j;\n            f[i + 1] = j;\n        }\n        int j = 0;\n        long long cnt = 0;\n        for (char c : s) {\n            while (j && c != p[j]) j = f[j];\n            if (c == p[j]) ++j;\n            if (j == m) { ++cnt; j = f[j]; }\n        }\n        out << cnt << \"\\n\";\n    }\n}\n";
W["hsga-cp19-motif"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    string s; in >> s;\n    int q; in >> q;\n    while (q--) {\n        string p; in >> p;\n        // WRONG: non-overlapping find loop \u2014 \"aa\" in \"aaaaa\" counts 2, not 4.\n        long long cnt = 0;\n        size_t pos = 0;\n        while ((pos = s.find(p, pos)) != string::npos) { ++cnt; pos += p.size(); }\n        out << cnt << \"\\n\";\n    }\n}\n";
