R["hsga-p19-euler"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Euler tour + BIT: point assign, subtree sum.\n    int n; int q; in >> n >> q;\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) { int p; in >> p; ch[p].push_back(v); }\n    vector<int> tin(n + 1, 0), tout(n + 1, 0);\n    int timer = 0;\n    {\n        // iterative euler with child-index stack\n        vector<pair<int, int>> st;\n        st.push_back({1, 0});\n        tin[1] = ++timer;\n        while (!st.empty()) {\n            int v = st.back().first;\n            int i = st.back().second;\n            if (i < (int)ch[v].size()) {\n                ++st.back().second;\n                int c = ch[v][i];\n                tin[c] = ++timer;\n                st.push_back({c, 0});\n            } else {\n                tout[v] = timer;\n                st.pop_back();\n            }\n        }\n    }\n    vector<long long> fen(n + 1, 0);\n    auto upd = [&](int i, long long d) { for (; i <= n; i += i & (-i)) fen[i] += d; };\n    auto pref = [&](int i) { long long s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };\n    vector<long long> cur(n + 1, 0);\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) {\n            int v; long long x; in >> v >> x;\n            upd(tin[v], x - cur[v]);\n            cur[v] = x;\n        } else {\n            int v; in >> v;\n            out << pref(tout[v]) - pref(tin[v] - 1) << \"\\n\";\n        }\n    }\n}\n";
W["hsga-p19-euler"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; int q; in >> n >> q;\n    vector<int> par(n + 1, 0);\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) { in >> par[v]; ch[par[v]].push_back(v); }\n    vector<long long> val(n + 1, 0);\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) { int v; long long x; in >> v >> x; val[v] = x; }\n        else {\n            int v; in >> v;\n            // WRONG: re-walks the whole subtree per query \u2014 O(n) each;\n            // 100000 subtree queries on n = 200000 is far over budget.\n            long long s = 0;\n            vector<int> st(1, v);\n            while (!st.empty()) {\n                int u = st.back();\n                st.pop_back();\n                s += val[u];\n                for (int c : ch[u]) st.push_back(c);\n            }\n            out << s << \"\\n\";\n        }\n    }\n}\n";
R["hsga-p19-euler"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Euler tour + BIT: point assign, subtree sum.\n    int n; int q; in >> n >> q;\n    vector<vector<int>> ch(n + 1);\n    for (int v = 2; v <= n; ++v) { int p; in >> p; ch[p].push_back(v); }\n    vector<int> tin(n + 1, 0), tout(n + 1, 0);\n    int timer = 0;\n    {\n        // iterative euler with child-index stack\n        vector<pair<int, int>> st;\n        st.push_back({1, 0});\n        tin[1] = ++timer;\n        while (!st.empty()) {\n            int v = st.back().first;\n            int i = st.back().second;\n            if (i < (int)ch[v].size()) {\n                ++st.back().second;\n                int c = ch[v][i];\n                tin[c] = ++timer;\n                st.push_back({c, 0});\n            } else {\n                tout[v] = timer;\n                st.pop_back();\n            }\n        }\n    }\n    vector<long long> fen(n + 1, 0);\n    auto upd = [&](int i, long long d) { for (; i <= n; i += i & (-i)) fen[i] += d; };\n    auto pref = [&](int i) { long long s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };\n    vector<long long> cur(n + 1, 0);\n    while (q--) {\n        int tp; in >> tp;\n        if (tp == 1) {\n            int v; long long x; in >> v >> x;\n            upd(tin[v], x - cur[v]);\n            cur[v] = x;\n        } else {\n            int v; in >> v;\n            out << pref(tout[v]) - pref(tin[v] - 1) << \"\\n\";\n        }\n    }\n}\n";
