R["hsga-p19-borders"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Number of border lengths = steps in the failure chain.\n    string s; in >> s;\n    int n = (int)s.size();\n    vector<int> f(n + 1, 0);\n    for (int i = 1; i < n; ++i) {\n        int j = f[i];\n        while (j && s[i] != s[j]) j = f[j];\n        if (s[i] == s[j]) ++j;\n        f[i + 1] = j;\n    }\n    int j = f[n];\n    long long cnt = 0;\n    while (j) { ++cnt; j = f[j]; }\n    out << cnt << \"\\n\";\n}\n";
W["hsga-p19-borders"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string s; in >> s;\n    int n = (int)s.size();\n    // WRONG: verifies every candidate length by direct comparison \u2014\n    // O(n^2); n = 1e6 is 1e12 character comparisons.\n    long long cnt = 0;\n    for (int l = 1; l < n; ++l) {\n        bool ok = true;\n        for (int i = 0; i < l && ok; ++i) ok = (s[i] == s[n - l + i]);\n        if (ok) ++cnt;\n    }\n    out << cnt << \"\\n\";\n}\n";
