R["hsga-p19-maxxor"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Max pairwise XOR via a binary trie (30 levels).\n    int n; in >> n;\n    vector<unsigned> a(n);\n    for (auto& x : a) in >> x;\n    struct Node { int ch[2] = {0, 0}; };\n    vector<Node> t(1);\n    auto insert = [&](unsigned x) {\n        int cur = 0;\n        for (int b = 29; b >= 0; --b) {\n            int bit = (x >> b) & 1u;\n            if (!t[cur].ch[bit]) { t[cur].ch[bit] = (int)t.size(); t.push_back(Node()); }\n            cur = t[cur].ch[bit];\n        }\n    };\n    for (unsigned x : a) insert(x);\n    unsigned best = 0;\n    for (unsigned x : a) {\n        int cur = 0;\n        unsigned v = 0;\n        for (int b = 29; b >= 0; --b) {\n            int bit = (x >> b) & 1u;\n            int want = 1 - bit;\n            if (t[cur].ch[want]) { v |= 1u << b; cur = t[cur].ch[want]; }\n            else cur = t[cur].ch[bit];\n        }\n        best = max(best, v);\n    }\n    out << best << \"\\n\";\n}\n";
W["hsga-p19-maxxor"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int n; in >> n;\n    vector<unsigned> a(n);\n    for (auto& x : a) in >> x;\n    // WRONG: all-pairs scan \u2014 n = 200000 is 2e10 comparisons.\n    unsigned best = 0;\n    for (int i = 0; i < n; ++i)\n        for (int j = i + 1; j < n; ++j)\n            best = max(best, a[i] ^ a[j]);\n    out << best << \"\\n\";\n}\n";
