R["hsga-cp20-cargo"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Binary search the answer: min max-segment-sum with k contiguous parts.\n    int n; int k; in >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) in >> x;\n    auto parts = [&](long long limit) {\n        int cnt = 1;\n        long long cur = 0;\n        for (long long x : a) {\n            if (cur + x > limit) { ++cnt; cur = x; }\n            else cur += x;\n        }\n        return cnt;\n    };\n    long long lo = *max_element(a.begin(), a.end()), hi = 0;\n    for (long long x : a) hi += x;\n    while (lo < hi) {\n        long long mid = lo + (hi - lo) / 2;\n        if (parts(mid) <= k) hi = mid;\n        else lo = mid + 1;\n    }\n    out << lo << \"\\n\";\n}\n";
