R["hsga-p20-maze"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // BFS over (row, col, hasKey).\n    int R, C; in >> R >> C;\n    vector<string> g(R);\n    for (auto& row : g) in >> row;\n    int sr = 0, sc = 0, kr = -1, kc = -1;\n    for (int r = 0; r < R; ++r)\n        for (int c = 0; c < C; ++c) {\n            if (g[r][c] == 'S') { sr = r; sc = c; }\n            if (g[r][c] == 'K') { kr = r; kc = c; }\n        }\n    vector<vector<array<char, 2>>> seen(R, vector<array<char, 2>>(C, {0, 0}));\n    vector<array<int, 3>> q;\n    q.push_back({sr, sc, 0});\n    seen[sr][sc][0] = 1;\n    int head = 0, dist = 0;\n    while (head <= (int)q.size() - 1) {\n        int sz = (int)q.size();\n        for (int t = head; t < sz; ++t) {\n            auto [r, c, hk] = q[t];\n            if (g[r][c] == 'E') { out << dist << \"\\n\"; return; }\n            int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};\n            for (int d4 = 0; d4 < 4; ++d4) {\n                int nr = r + dr[d4], nc = c + dc[d4];\n                if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;\n                char ch = g[nr][nc];\n                if (ch == '#') continue;\n                if (ch == 'D' && !hk) continue;\n                int nhk = hk || (nr == kr && nc == kc);\n                if (!seen[nr][nc][nhk]) {\n                    seen[nr][nc][nhk] = 1;\n                    q.push_back({nr, nc, nhk});\n                }\n            }\n        }\n        head = sz;\n        ++dist;\n    }\n    out << -1 << \"\\n\";\n}\n";
W["hsga-p20-maze"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    int R, C; in >> R >> C;\n    vector<string> g(R);\n    for (auto& row : g) in >> row;\n    int sr = 0, sc = 0;\n    for (int r = 0; r < R; ++r)\n        for (int c = 0; c < C; ++c)\n            if (g[r][c] == 'S') { sr = r; sc = c; }\n    // WRONG: plain BFS \u2014 the key state is dropped, so the door is either\n    // an impassable wall (key forgotten) or a free shortcut (stateless);\n    // either way the path length is wrong on keyed mazes.\n    vector<vector<char>> seen(R, vector<char>(C, 0));\n    vector<pair<int, int>> q;\n    q.push_back({sr, sc});\n    seen[sr][sc] = 1;\n    int head = 0, dist = 0;\n    while (head <= (int)q.size() - 1) {\n        int sz = (int)q.size();\n        for (int t = head; t < sz; ++t) {\n            auto [r, c] = q[t];\n            if (g[r][c] == 'E') { out << dist << \"\\n\"; return; }\n            int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};\n            for (int d4 = 0; d4 < 4; ++d4) {\n                int nr = r + dr[d4], nc = c + dc[d4];\n                if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;\n                if (g[nr][nc] == '#' || g[nr][nc] == 'D') continue;\n                if (!seen[nr][nc]) { seen[nr][nc] = 1; q.push_back({nr, nc}); }\n            }\n        }\n        head = sz;\n        ++dist;\n    }\n    out << -1 << \"\\n\";\n}\n";
