R["hsga-p20-digitdp"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    // Count x in [1, N] with digitSum(x) % k == 0 (digit DP).\n    string N; int k; in >> N >> k;\n    int L = (int)N.size();\n    vector<vector<long long>> fr(L + 1, vector<long long>(k, 0));\n    fr[L][0] = 1;\n    for (int i = L - 1; i >= 0; --i)\n        for (int m = 0; m < k; ++m)\n            for (int d = 0; d <= 9; ++d)\n                fr[i][(m + d) % k] += fr[i + 1][m];\n    long long total = 0;\n    int mod = 0;\n    for (int i = 0; i < L; ++i) {\n        int di = N[i] - '0';\n        for (int d = 0; d < di; ++d)\n            total += fr[i + 1][(k - (mod + d) % k) % k];  // suffix supplies the complement\n        mod = (mod + di) % k;\n    }\n    if (mod == 0) ++total;\n    out << total - 1 << \"\\n\";  // exclude x = 0\n}\n";
W["hsga-p20-digitdp"] = "#include <iostream>\n#include <algorithm>\n#include <vector>\n#include <string>\n#include <functional>\nusing namespace std;\nvoid solve(std::istream& in, std::ostream& out) {\n\n    string N; int k; in >> N >> k;\n    // WRONG: enumerates every number up to N \u2014 N = 1e18 never finishes.\n    long long x = 1, cnt = 0;\n    while (true) {\n        long long t = x, ds = 0;\n        while (t) { ds += t % 10; t /= 10; }\n        if (ds % k == 0) ++cnt;\n        if (x == stoll(N)) break;\n        ++x;\n    }\n    out << cnt << \"\\n\";\n}\n";
